00080     public static function getSectionName($name, $args = array())
00081     {
00082         return ucfirst($name) . (!empty($args) ? '-' . md5(serialize($args)) : '');
00083     }
00084 
00094     public static function getSectionContent($name, $class, $args = array())
00095     {
00096         $baseMethod = 'get' . ucfirst($name);
00097         $args = $args == null ? array() : $args;
00098         return '[' . self::getSectionName($name, $args) . ']' . PHP_EOL .
00099             call_user_func_array($class . '::' . $baseMethod, $args);
00100     }
