00115     public static function getActionRun($action, $args = array(), $item = array(), $waitUntilTerminated = true)
00116     {
00117         global $bearsamppRoot, $bearsamppCore;
00118         $args = $args == null ? array() : $args;
00119 
00120         $argImp = '';
00121         foreach ($args as $arg) {
00122             $argImp .= ' ' . base64_encode($arg);
00123         }
00124 
00125         $result = 'Action: run; ' .
00126             'FileName: "' . Path::getPhpExe(true) . '"; ' .
00127             'Parameters: "' . Core::isRoot_FILE . ' ' . $action . $argImp . '"; ' .
00128             'WorkingDir: "' . Path::getCorePath(true) . '"';
00129 
00130         if (!empty($item)) {
00131             $result = 'Type: item; ' . $result .
00132                 '; Caption: "' . $item[self::ITEM_CAPTION] . '"' .
00133                 (!empty($item[self::ITEM_GLYPH]) ? '; Glyph: "' . $item[self::ITEM_GLYPH] . '"' : '');
00134         } elseif ($waitUntilTerminated) {
00135             $result .= '; Flags: waituntilterminated';
00136         }
00137 
00138         return $result;
00139     }
00140 
00152     public static function getActionMulti($action, $args = array(), $item = array(), $disabled = false, $class = false)
00153     {
00154         $action = 'action' . ucfirst($action);
00155         $args = $args == null ? array() : $args;
00156         $sectionName = self::getSectionName($action, $args);
00157 
00158         $call = 'Action: multi; Actions: ' . $sectionName;
00159 
00160         if (!empty($item)) {
00161             $call = 'Type: item; ' . $call .
00162             '; Caption: "' . $item[self::ITEM_CAPTION] . '"' .
00163             (!empty($item[self::ITEM_GLYPH]) ? '; Glyph: "' . $item[self::ITEM_GLYPH] . '"' : '');
00164         } else {
00165             $call .= '; Flags: waituntilterminated';
00166         }
00167 
00168         return array($call, self::getSectionContent($action, $class, $args));
00169     }
